<script setup lang="ts">import{ref}from"vue";import{api,ApiError}from"../api/client";import{useRouter}from"vue-router";const router=useRouter(),username=ref(""),password=ref(""),error=ref("");async function submit(){try{await api("/auth/register",{method:"POST",body:JSON.stringify({username:username.value,password:password.value})});router.push("/")}catch(e){error.value=e instanceof ApiError?e.message:"注册失败"}}</script>
<template><main class="connect-shell"><form class="connect-card" @submit.prevent="submit"><p class="eyebrow">DOMAINSPRITE</p><h1>创建普通用户</h1><p class="muted">仅在管理员开放注册时可用，域名权限仍需管理员分配。</p><label>用户名<input v-model="username" required minlength="3"></label><label>密码<input v-model="password" type="password" required minlength="10"></label><div v-if="error" class="alert error">{{error}}</div><button class="primary wide">注册</button><router-link class="quiet-link" to="/">返回登录</router-link></form></main></template>
